```python
import asyncio
from typing import Awaitable, Callable


async def run_tasks(
    tasks: list[Callable[[], Awaitable[None]]],
    max_concurrent: int,
) -> None:
    if max_concurrent < 1:
        raise ValueError("max_concurrent must be at least 1")
    if not tasks:
        return

    sem = asyncio.Semaphore(max_concurrent)

    async def run_one(task: Callable[[], Awaitable[None]]) -> None:
        async with sem:
            await task()

    all_tasks = {asyncio.create_task(run_one(t)) for t in tasks}

    try:
        done, pending = await asyncio.wait(
            all_tasks, return_when=asyncio.FIRST_EXCEPTION
        )
    except asyncio.CancelledError:
        # Ctrl+C or external cancellation. Cancel pending tasks so
        # their finally blocks (cleanup) have a chance to run.
        for t in all_tasks:
            if not t.done():
                t.cancel()
        await asyncio.wait(all_tasks)
        raise

    # Collect the first non-cancellation exception
    first_exc = None
    for t in done:
        if t.cancelled():
            continue
        exc = t.exception()
        if exc is not None:
            first_exc = exc
            break

    # If there's a failure or tasks still running, cancel and wait
    if first_exc is not None or pending:
        for t in pending:
            if not t.done():
                t.cancel()
        if pending:
            await asyncio.wait(pending)

    if first_exc is not None:
        raise first_exc
```

